HPB_st.name='HPB'; 
HPB_st.lat=47.8015;
HPB_st.lon=11.0096;
HPB_st.alt=985;
HPB_st.env='Mt';
HPB_st.footp='RB';
%%

HPB_rd=read_ebas_merged_STN('C:\github_trend\raw_data\merged_Hohenpeissenberg.nc', HPB_st); %[output:4dd4805e]

names_rd=fieldnames(HPB_rd);
%%
% try to take also data
HPB_rd_12=timetable(datetime(SC_HPB(:,1:6)));
HPB_rd_12.BsB_S12=SC_HPB(:,10);
HPB_rd_12.BsG_S12=SC_HPB(:,11);
HPB_rd_12.BsR_S12=SC_HPB(:,12);

HPB_rd_12.BbsB_S12=SC_HPB(:,13);
HPB_rd_12.BbsG_S12=SC_HPB(:,14);
HPB_rd_12.BbsR_S12=SC_HPB(:,15);
HPB_re_12=retime(HPB_rd_12,'daily',@nanmedian);
%%
HPB_rdabs_12=timetable(datetime(HPB_AE_GAW(:,1:6)));
HPB_rdabs_12.BaR_AE10=HPB_AE_GAW(:,9);
HPB_rdabs_12.BaR_AE10(HPB_rdabs_12.BaR_AE10<-90)=NaN;
HPB_rdabs_12=retime(HPB_rdabs_12,'daily',@nanmedian);
%%


%%
datevec(HPB_rd.Time(1)) % 2004 %[output:793a143e]
datevec(HPB_rd.Time(end)) %2025 %[output:844d8e7d]
prctile(HPB_rd.U370_S,[5 50 95]) % 10-47% but rh decreases in recent year --> compute RH and dry trends %[output:2a35b27f]
plotFigControl(HPB_rd,HPB_st.name); %[output:704db171] %[output:93a0be49] %[output:45f36977] %[output:5aeeaac8] %[output:98c22414] %[output:6f3c42c0] %[output:118c8fdf]
% 1 size cut, ok
% sc: ok,  no negatives, not so clear seasonlity, somewhat higher in winter
% abs: 2 size cut, max in summer, no negatives
% figure
% plot(HPB_rd.Time,HPB_rd.U_S11,'.');
%%
% homogeneise abAE10-MAAP
% common period 1.1.2004 - 1.1.2008
P_AE10_MAAP=timerange('2004-01-01','2008-01-01');
ratio_STN=nanstd(HPB_rd.Ba6600_A(P_AE10_MAAP)./HPB_rdabs_12.BaR_AE10(P_AE10_MAAP)) % 0.1375 %[output:0d51bc8d]
ratio_mean=nanmean(HPB_rd.Ba6600_A(P_AE10_MAAP))/nanmean(HPB_rdabs_12.BaR_AE10(P_AE10_MAAP)) % 0.1766 %[output:579c7e80]
ratio_median=nanmedian(HPB_rd.Ba6600_A(P_AE10_MAAP))/nanmedian(HPB_rdabs_12.BaR_AE10(P_AE10_MAAP)) % 0.1413 %[output:28921c7d]
figure; %[output:97d41a64]
plot(HPB_rd.Ba6600_A(P_AE10_MAAP),HPB_rdabs_12.BaR_AE10(P_AE10_MAAP)-20,'.'); %difficult to do a basic fit %[output:97d41a64]
ylabel('Ba AE10'); %[output:97d41a64]
xlabel('Ba MAAP'); %[output:97d41a64]
grid on; %[output:97d41a64]
legend('period 2004-2008','fit') %[output:0e7a1534] %[output:97d41a64]
% fit between both data: slope 0.9955x+0.1021
fit_test=robustfit(HPB_rd.Ba6600_A(P_AE10_MAAP),HPB_rdabs_12.BaR_AE10(P_AE10_MAAP)) % 21.27, slope=0.4615 %[output:785f13d1]
% 1/slope fit and robust fit =0.93: use it as constant
cte_PSAP_CLAP=0.93;
%%
   % time serie PSAP+CLAP
P1=timerange('2008-10-11','2011-08-15');
P2=timerange('2011-08-15','2026-01-01');

% 
LLN_rd2.BaG0_psap_clap=NaN(size(HPB_rd_Ba66000_A));
LLN_rd2.BaG0_psap_clap(P1)=HPB_rdabs_12.BaR_AE10(P1).*cte_PSAP_CLAP; 
LLN_rd2.BaG0_psap_clap(P2)=HPB_rd_Ba66000_A(P2);

LLN_rd2.BaG1_psap_clap=NaN(size(LLN_rd2.BaG1_A12clap));
LLN_rd2.BaG1_psap_clap(P1)=LLN_rd2.BaG1_A11psap(P1).*cte_PSAP_CLAP; 
LLN_rd2.BaG1_psap_clap(P2)=LLN_rd2.BaG1_A12clap(P2);

% do the same with B and R for abs exp
LLN_rd2.BaB0_psap_clap=NaN(size(LLN_rd2.BaB0_A12clap));
LLN_rd2.BaB0_psap_clap(P1)=LLN_rd2.BaB0_A11psap(P1).*cte_PSAP_CLAP; 
LLN_rd2.BaB0_psap_clap(P2)=LLN_rd2.BaB0_A12clap(P2);

LLN_rd2.BaR0_psap_clap=NaN(size(LLN_rd2.BaR0_A12clap));
LLN_rd2.BaR0_psap_clap(P1)=LLN_rd2.BaR0_A11psap(P1).*cte_PSAP_CLAP; 
LLN_rd2.BaR0_psap_clap(P2)=LLN_rd2.BaR0_A12clap(P2);
%%
% Bp detection of homogenise abs + AE
names_abs_tr={'BaB0_psap_clap', 'BaG0_psap_clap','BaR0_psap_clap', 'Bac3_A81ae31'};
break_LLN_abs=change_point_analysis_Def(LLN_rd2,names_abs_tr,0.05,'LLN','abs three homogeneisation');
T_LLN_abs=make_table_breakpoints_def(break_LLN_abs);

%%
lambdaSC=[450;550;700]*ones(1,4);
lambdaAE=[467;530;660]*ones(1,4);
lambdaAE7=[370 470 520 590 660 880 950];
HPB_cal=compute_exp_SSA(HPB_rd,lambdaSC, lambdaAE);
plotFigControl_cal(HPB_cal,HPB_st.name);
%%
%Questions:
%problems:

%humidity: there is large variation in max humidity with much lower values since 2015 (2013): is there any change in the dryer ?

% scat+ backscat: it seems that there is a kind of rupture in end 2014/2015 with lower values thereafter. Any idea?
% scat exponent: there is several issues concerning all pair-wise exponents (see figure) with break points in February 2009, April 2018 and April 2016. Do you have explanations ?
%backscattering fraction: it seems to have a kind of rupture in April 2012, January 2015 and April 2017. Should the high values in September be deleted?

%abs MAAP: are the high values in February 2012 real ? should be deleted ?

%N: there is also something strange (very high values) in February 2012:
%%
HPB_tr=HPB_rd;
HPB_tr.y=year(HPB_tr.Time);
% begin at the beginning of a year: 2004 for absorption
%end 2017
P=timerange('2004-01-01','2018-01-01');
HPB_tr=HPB_tr(P,:);

% PM1: 2012-2015: too short, not to analyse
%abs: use AE31 also only until end of 2015.
names=fieldnames(HPB_tr);
c= startsWith(names,["T1";"T0";"T_";"P_";"P1_";"P0_";"N";"Uu";"U1"]) ;
N=names(c);
for i=1:length(N)
    HPB_tr.(N{i})=[];
end

%begin 2006 for scattering: already NAN
%trend in RH and dry to compute
%abs: ok
% probably not much change for exp and BbsF dry: forget
HPB_tr.BsB_S11_dry=[];
HPB_tr.BsR_S11_dry=[];
HPB_tr.BbsB_S11_dry=[];
HPB_tr.BbsR_S11_dry=[];

% not same wavelength, abs should be corrected for SSA trend

HPB_cal2=compute_exp_SSA(HPB_tr,lambdaSC, lambdaAE);
HPB_cal2.SSA=HPB_tr.BsG_S11./(HPB_tr.BsG_S11+HPB_tr.BaR_A11.*(637/550));
HPB_cal2.BbsFG=HPB_tr.BbsG_S11./HPB_tr.BsG_S11;
HPB_cal2.expS_bg=real(-log(HPB_tr.BsB_S11./HPB_tr.BsG_S11)/log(lambdaSC(1)/lambdaSC(2)));
HPB_cal2.expS_bg3=[];
HPB_cal2.expS_br3=[];
HPB_cal2.expS_gr3=[];
HPB_cal2.SSA311=[];
HPB_cal2.SSA321=[];
HPB_cal2.BbsFG2=[];
HPB_tr=outerjoin(HPB_tr, HPB_cal2);

%do not compute trend on scat and backscat b/r
HPB_tr.BsB_S11=[];
HPB_tr.BsR_S11=[];
HPB_tr.BbsB_S11=[];
HPB_tr.BbsR_S11=[];

%exp: use bg,not sure that it is homogeneous
%BbsF: probably wrong increasing trend due to instrumental problem.
%%
HPB_result= all_trend_STN(HPB_tr,HPB_st); 
%%
%there is rupture in BbsF and in expS: not considered
HPB_result_D=HPB_result;
s=startsWith( HPB_result_D.parameter,["expS";"BbsF"]);
HPB_result_D=HPB_result_D(~s,:);

